function record(s,r){s.ledger.unshift({day:s.day,week:s.week,...r});s.ledger=s.ledger.slice(0,120);}
function start(s,id){const q=G.regionalPlanQuote(s,id);s.cash-=q.cost;state(s).project={model:id,start:s.week,lastWeek:s.week,progress:0,need:8,cost:q.cost};record(s,{title:q.name+' / oppbygging',gross:0,cost:q.cost,net:-q.cost,status:'Ledelse og avtaler, ikke en omsettelig eiendel'});G.notifyScene(s,{id:'regional-start-'+s.week,kind:'regional',speaker:q.speaker,title:'Flere bord, et annet ansvar',text:q.text+' Åtte uker med leveranser til minst to byer gjør avtalen operativ. Lederne følger opp.'});return 'Regionavtalen er startet. Den bygges mens rutene går.';}
function week(s){const a=state(s),p=a.project;if(!p||s.ended||p.lastWeek>=s.week)return;p.lastWeek=s.week;const delivered=new Set(s.ledger.filter(r=>r.week===s.week&&r.route&&r.gross>0).map(row=>s.routes.find(r=>r.id===row.route)?.city).filter(c=>c!==undefined));if(delivered.size>=2&&s.crew.loyalty>=55)p.progress++;if(p.progress<p.need)return;a.model=p.model;a.lastChange=s.week;a.history.unshift({...p,finished:s.week});a.history=a.history.slice(0,20);a.project=null;const m=model(s);G.notifyScene(s,{id:'regional-finish-'+s.week,kind:'regional',speaker:m.speaker,title:m.name+' er på plass',text:m.text+' Kontrollspenn nå: '+G.controlLimit(s)+' regioner.'});G.refreshRank(s);}
G.registerSystem({id:'regional',migrate:state,validate(s){if(s.regional===undefined)return true;const a=s.regional;return !!a&&a.version===1&&G.REGIONAL_MODELS.some(m=>m.id===a.model)&&Number.isInteger(a.lastChange)&&a.lastChange>=-100&&a.lastChange<=s.week&&Array.isArray(a.history)&&a.history.length<=20&&a.history.every(p=>p&&G.REGIONAL_MODELS.some(m=>m.id===p.model)&&Number.isInteger(p.finished)&&p.finished<=s.week&&Number.isFinite(p.cost)&&p.cost>=0)&&(!a.project||(G.REGIONAL_MODELS.some(m=>m.id===a.project.model)&&Number.isInteger(a.project.start)&&a.project.start<=s.week&&(a.project.lastWeek===undefined||Number.isInteger(a.project.lastWeek)&&a.project.lastWeek>=a.project.start&&a.project.lastWeek<=s.week)&&Number.isInteger(a.project.progress)&&a.project.progress>=0&&a.project.progress<8&&a.project.need===8&&Number.isFinite(a.project.cost)&&a.project.cost>=0));},hooks:{week},actions:{regionalPlan:{guard(s,id){const q=G.regionalPlanQuote(s,id);return q?q.reason:'Velg en kjent organisasjonsform.';},handler:start}}});
if(typeof module!=='undefined')module.exports=G;
